    id: 'custom-national-dex',
    label: 'National Pokédex Unlock',
    description: 'Upgrades your Pokédex to the National Pokédex right away, instead of after beating the Elite Four and catching 60 Kanto Pokémon (FireRed and LeafGreen) or entering the Hall of Fame (Emerald). In FireRed and LeafGreen it also lets Kanto Pokémon evolve into later species, and Celio needs it before he sends you on the errand that earns the Rainbow Pass, which the Aurora and Mystic Tickets need. It opens up trading too: a game without the National Pokédex can’t trade away or be sent Pokémon from outside its regional Pokédex, or Eggs. With this card on both games, Emerald and FireRed or LeafGreen trade any Pokémon both ways, right away with switch.gblink.io’s National Dex bypass on, otherwise once both players have entered the Hall of Fame and the FireRed or LeafGreen player has finished the Sevii Islands story. You need a Pokédex first.',
